-- UDU: create the source-preserving BOQ hierarchy and attach current operational items.
-- Source sheet is explicitly the single approved sheet "Trainer & UDU Office".
begin;
create table if not exists public.boq_sections (
 id uuid primary key default gen_random_uuid(),
 source_sheet text not null default 'Trainer & UDU Office',
 source_row integer not null,
 node_code text not null,
 description text not null,
 level smallint not null check(level between 1 and 3),
 parent_id uuid references public.boq_sections(id) on delete restrict,
 sort_order integer not null,
 source_color text not null,
 source_qty numeric,
 source_uom text,
 source_total_price numeric,
 is_active boolean not null default true,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id),
 unique(source_sheet,source_row)
);
alter table public.boq_items add column if not exists parent_section_id uuid references public.boq_sections(id) on delete restrict;
alter table public.boq_items add column if not exists source_excel_row integer;
alter table public.boq_items add column if not exists baseline_quantity numeric;
alter table public.boq_items add column if not exists baseline_unit_rate numeric;
update public.boq_items set source_excel_row=source_row-5
 where source_sheet='Trainer & UDU Office' and source_row is not null and source_excel_row is null;
update public.boq_items set baseline_quantity=quantity,baseline_unit_rate=unit_rate
 where baseline_quantity is null or baseline_unit_rate is null;
insert into public.boq_sections(source_sheet,source_row,node_code,description,level,sort_order,source_color,source_qty,source_uom,source_total_price)
select 'Trainer & UDU Office',x.source_row,x.node_code,x.description,x.level,x.source_row,x.source_color,x.source_qty,x.source_uom,x.source_total_price
