on conflict(source_sheet,source_row) do update set node_code=excluded.node_code,description=excluded.description,level=excluded.level,sort_order=excluded.sort_order,source_color=excluded.source_color,source_qty=excluded.source_qty,source_uom=excluded.source_uom,source_total_price=excluded.source_total_price,updated_at=now();
alter table public.boq_sections enable row level security;
drop policy if exists boq_sections_read_authenticated on public.boq_sections;
create policy boq_sections_read_authenticated on public.boq_sections for select to authenticated using(true);
drop policy if exists boq_sections_manage on public.boq_sections;
create policy boq_sections_manage on public.boq_sections for all to authenticated
using(public.current_user_role() in ('admin','site_manager'))
with check(public.current_user_role() in ('admin','site_manager'));
